CREATE TABLE pgcolumns_1.t(id integer);
INSERT INTO pgcolumns_1.t VALUES(7);
CREATE TABLE pgcolumns_1.occupied(id integer);
CREATE VIEW pgcolumns_1.v AS SELECT id FROM pgcolumns_1.t;
CREATE TYPE pgcolumns_1.c AS (id integer, flag boolean);
CREATE TYPE pgcolumns_1.sh;
CREATE TABLE pgcolumns_1.receipt AS SELECT c.oid,c.relname,c.relkind,c.reloftype,a.attnum,a.attname,a.attnotnull,a.atthasdef FROM pg_catalog.pg_class c LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE c.relnamespace='pgcolumns_1'::regnamespace AND c.relname<>'receipt'

